diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..8025a2b
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,22 @@
+import { AppError } from "../errors.js";
+import { importSalesRows } from "../domain/sales.js";
+import { parseCsv } from "./csv.js";
+
+/** Parses a sales CSV and imports the whole file atomically. */
+export function importSales(store, text) {
+  const lines = text.split(/\r?\n/).filter((line) => line.trim());
+  for (const [index, line] of lines.entries()) {
+    if (!/^(?:[^",]*|"(?:[^"]|"")*")(?:,(?:[^",]*|"(?:[^"]|"")*"))*$/.test(line))
+      throw new AppError("bad_request", { reason: `row ${index + 1}: malformed CSV` });
+  }
+  const [header = [], ...values] = parseCsv(text);
+  const keys = header.map((key) => key.trim());
+  if (keys.length !== 4 || !["ticket", "soldAt", "dishId", "qty"].every((key) => keys.includes(key)))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty columns" });
+  const rows = values.map((values, index) => {
+    if (values.length !== keys.length)
+      throw new AppError("bad_request", { reason: `row ${index + 2}: wrong number of fields` });
+    return Object.fromEntries(keys.map((key, index) => [key, values[index].trim()]));
+  });
+  return importSalesRows(store, rows);
+}
